request.getRequestDispatcher(&quot;/scope2.jsp&quot;).forward(request,response);
%&gt;
&lt;/body&gt;
scope2.jsp 页面
&lt;body&gt;
&lt;h1&gt;scope2.jsp 页面&lt;/h1&gt;
pageContext 域是否有值：&lt;%=pageContext.getAttribute(&quot;key&quot;)%&gt; &lt;br&gt;
request 域是否有值：&lt;%=request.getAttribute(&quot;key&quot;)%&gt; &lt;br&gt;
