&lt;/bean&gt;

&lt;bean id=&quot;hello-child&quot; parent=&quot;hello&quot;&gt;
    &lt;property name=&quot;content&quot; value=&quot;I`m hello-child&quot;/&gt;
&lt;/bean&gt;
