快速排序
循序渐进进行运行：
快排首先涉及到划分：
Partition过程：给定一个数组arr，和一个整数num。请把小于等于num的数放在数组的左边，大于num的数放在数组的右边。要求额外空间复杂度O(1)，时间复杂度O(N)
public static int partition(int[] arr, int L, int R) {
        if (L &gt; R) {
            return -1;
        }
        if (L == R) {
            return L;
        }
        //规定左边界与右边界
        //左边界刚开始确定为L -1， 右边界刚开始确定为 R + 1，然后将arr[R]作为num
        int lessEqual = L - 1;
        int index = L;
        while (index &lt; R) {
            if (arr[index] &lt;= arr[R]) {
                //这是第一种情况：此值小于等于要求值，将此值放于左区间内，左区间向前移动
                swap(arr,index,++lessEqual);
            }
            index++;
        }
        //将此值放于左区间边界
        swap(arr,++lessEqual,R);
        return lessEqual;
    }

    public static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
荷兰国旗问题
给定一个数组arr，和一个整数num。请把小于num的数放在数组的左边，等于num的数放在中间，大于num的数放在数组的右边。
要求额外空间复杂度O(1)，时间复杂度O(N)
public  static int[] netherlandsFlag(int[] arr, int L, int R) {
        if (L &gt; R) {
            return new int[] {-1, -1};
        }
        if (L == R) {
            return new int[] {L, R};
        }
        //规定最开始的左边界 与 右边界 将arr[R]作为num
        int less = L - 1;
        int more = R;
        int index = L;
        //当最开始值小于边界值时
        while (index &lt; more) {
            if (arr[index] &lt; arr[R]) {
                //此值与num交换 同时index向前移动 左区间向前移动
                swap(arr,index++,++less);
            } else if (arr[index] == arr[R]) {
                //相等时 index向前移动
                index++;
            } else {
                //大于时 此值交换，index保持不变
                swap(arr,index,--more);
            }
        }
        //最后， 将num放入右区间 划分结束
        //0..less less+1..more-1 more..R-1 R
        //o..less less+1..more more+1..R
        swap(arr,more,R);
        return new int[] {less + 1, more};
    }
