        }

    }


    public static class AComp implements Comparator&lt;Integer&gt;{

        // 如果返回负数，认为第一个参数应该拍在前面
        // 如果返回正数，认为第二个参数应该拍在前面
        // 如果返回0，认为谁放前面都行
