     * @param N 一共的层数
     * @param down 代表是凹还是凸
     */
    private static void printProcess(int i, int N, boolean down) {
        if (i &gt; N) {
            return;
        }
        printProcess(i + 1, N, true);
        System.out.println(down ? &quot;凹&quot;: &quot;凸&quot;);
