public static List&lt;String&gt; subs(String s){
        char[] str = s.toCharArray();
        String path = &quot;&quot;;
        List&lt;String&gt; ans = new ArrayList&lt;&gt;();
        process1(str, 0 , ans, path);
        return ans;
    }

    /**
     *  str[0..index-1]已经走过了！之前的决定，都在path上
     * @param str 固定参数
     * @param index 位置
     * @param ans 生成的子序列
     * @param path 之前的决定 放在path上
     */
    private static void process1(char[] str, int index, List&lt;String&gt; ans, String path) {
        if (index == str.length){
            ans.add(path);
            return;
        }
        // 没有要index位置的字符
        String no = path;
        process1(str, index + 1, ans, no);
        //要了index位置的字符
        String yes = path + String.valueOf(str[index]);
        process1(str, index + 1, ans, yes);
    }

	public static List&lt;String&gt; subsNoRepeat(String s) {
        char[] str = s.toCharArray();
        String path = &quot;&quot;;
        HashSet&lt;String&gt; set = new HashSet&lt;&gt;();
        process2(str, 0, set, path);
        List&lt;String&gt; ans = new ArrayList&lt;&gt;();
        for (String cur : set) {
            ans.add(cur);
        }
        return ans;
    }

    private static void process2(char[] str, int index, HashSet&lt;String&gt; set, String path) {
        if (index == str.length) {
            set.add(path);
            return;
        }
        String no = path;
        process2(str, index + 1, set, no);
        String yes= path + String.valueOf(str[index]);
        process2(str, index + 1, set, yes);
    }
打印不重复子序列
打印一个字符串的全部子序列，要求不要出现重复字面值的子序列
思路与解析
此题目中是上一个的延续，上面举的例子是字符串abc，如果是字符串aaa呢，是不是肯定有字面值重复的子序列。
解决办法：增加一个标志位，判断这个位置在本次中是否出现，如果已经出现，那么就代表重复，跳过，如果没有出现，那么本次就可以遍历，然后以此字符为基础，进行下一次遍历，如果符合要求，则会在最后加入res中，并且无重复子串。
public static ArrayList&lt;String&gt; permutationNoRepeat(String str) {
    ArrayList&lt;String&gt; res = new ArrayList&lt;&gt;();
    if (str == null || str.length() == 0) {
        return res;
    }
    char[] chs = str.toCharArray();
    process2(chs, 0, res);
    return res;
}

public static void process2(char[] str, int i, ArrayList&lt;String&gt; res) {
    if (i == str.length) {
        res.add(String.valueOf(str));
    }
    boolean[] visit = new boolean[26]; // visit[0 1 .. 25]
    for (int j = i; j &lt; str.length; j++) {
        if (!visit[str[j] - &#039;a&#039;]) {
            visit[str[j] - &#039;a&#039;] = true;
            swap(str, i, j);
            process2(str, i + 1, res);
            swap(str, i, j);
        }
    }
}

public static void swap(char[] chs, int i, int j) {
    char tmp = chs[i];
    chs[i] = chs[j];
    chs[j] = tmp;
}
逆序打印栈
给你一个栈，请你逆序这个栈，不能申请额外的数据结构，只能使用递归函数。 如何实现?
思路与解析
常规思路：再创建一个栈，然后将此栈中的全部内容压入另一个栈中，然后在打印。
本题解法：由于本题中不能再次创建对应的栈，可看下图：


定义一个函数getLastElement得到当前栈的栈底元素
定义一个函数reverseStack，保存当前栈的栈底元素，并把弹出栈底元素的栈传入reverseStack继续递归调用，直到栈为空返回，把每一层的i压入栈中就实现了栈的逆序。

public static void reverseStack(Stack&lt;Integer&gt; stack) {
        if (stack.isEmpty()) {
            return;
        }
        int i = getLastElement(stack);
        reverseStack(stack);
        stack.push(i);
    }

    public static int getLastElement(Stack&lt;Integer&gt; stack) {
        int result = stack.pop();
        if (stack.isEmpty()) {
            return result;
        } else {
            int last = getLastElement(stack);
            stack.push(result);
            return last;
        }
    }
常见的尝试模型
暴力递归说起来简单，就是一个个进行尝试，但是每种模型不一样，导致尝试的类型也会存在多样，一般情况下，会存在4种常见的尝试模型：

从左往右的尝试模型
范围上的尝试模型
多样本位置全对应的尝试模型
寻找业务限制的尝试模型

下面，我们将分别举一些例子，来说明每个类型的题目。
从左向右尝试
题目一
规定1和A对应、2和B对应、3和C对应…，那么一个数字字符串比如”111”就可以转化为:“AAA”、“KA”和”AK”，给定一个只有数字字符组成的字符串str，返回有多少种转化结果。
思路与解析
这道题目是Facebook的面试题，分析题目


数字1对应A，2对应B，…一直到26对应Z。数字0是没有对应的，也就是说，如果碰到0，没有转换结果。


仔细分析这道题，会发现在暴力递归中，这是一个从左往右的尝试模型。
什么是从左往右的尝试模型呢，之前写过的打印一个字符串的全部排列和子序列都是这种模型，简单来说，就是从左往右一个一个暴力尝试。


下面具体分析：

首先考虑base case，如果i位置来到字符串的终止位置，有两种可能：

字符串无字符了，返回空字符。
之前已经有转换好的结果，直接返回结果。


如果当前位置的字符是在3~9之间，i+1位置无论是什么，i和i+1连起来都不会超过26，所以这种情况下，i位置单独转换，然后去i+1位置递归
当前位置是1字符，i+1位置无论任何字符，i和i+1连起来都不会超过26，所以又有两种可能。

i位置单独转换，去i+1位置递归；
i和i+1一起转换，去i+2位置递归。


当前位置是2字符

如果i+1位置的字符是在[0~6]，i和i+1可以一起转换，去i+2位置递归。
其他情况，i单独转换，去i+1递归。



以上，就是此题目递归的过程。可以看下图（例子）：

因此，有如下代码：
public static int number(String str) {
		if (str == null || str.length() == 0) {
			return 0;
		}
		return process(str.toCharArray(), 0);
	}

	// i之前的位置，如何转化已经做过决定了, 不用再关心
	// i... 有多少种转化的结果
	public static int process(char[] str, int i) {
		if (i == str.length) { // base case
			return 1;
		}
		// i没有到终止位置
		if (str[i] == &#039;0&#039;) {
			return 0;
		}
		// str[i]字符不是‘0’
		if (str[i] == &#039;1&#039;) {
			int res = process(str, i + 1); // i自己作为单独的部分，后续有多少种方法
			if (i + 1 &lt; str.length) {
				res += process(str, i + 2); // (i和i+1)作为单独的部分，后续有多少种方法
			}
			return res;
		}
		if (str[i] == &#039;2&#039;) {
			int res = process(str, i + 1); // i自己作为单独的部分，后续有多少种方法
			// (i和i+1)作为单独的部分并且没有超过26，后续有多少种方法
			if (i + 1 &lt; str.length &amp;&amp; (str[i + 1] &gt;= &#039;0&#039; &amp;&amp; str[i + 1] &lt;= &#039;6&#039;)) {
				res += process(str, i + 2); // (i和i+1)作为单独的部分，后续有多少种方法
			}
			return res;
		}
		// str[i] == &#039;3&#039; ~ &#039;9&#039;
		return process(str, i + 1);
	}
