public static int win3(int[] arr) {
        if (arr == null || arr.length == 0) {
            return 0;
        }
        int[][] f = new int[arr.length][arr.length];
        int[][] s = new int[arr.length][arr.length];
        for (int j = 0; j &lt; arr.length; j++) {
            f[j][j] =arr[j];
            for (int i = j -1; i &gt;=0; i--) {
                f[i][j] = Math.max(arr[i] + s[i + 1][j], arr[j] + s[i][j - 1]);
                s[i][j] = Math.min(f[i + 1][j], f[i][j - 1]);
            }
        }
        return Math.max(f[0][arr.length - 1],s[0][arr.length - 1]);
    }
题目四
假设有排成一行的N个位置，记为1~N，N 一定大于或等于 2
开始时机器人在其中的M位置上(M 一定是 1~N 中的一个)
如果机器人来到1位置，那么下一步只能往右来到2位置；
如果机器人来到N位置，那么下一步只能往左来到 N-1 位置；
如果机器人来到中间位置，那么下一步可以往左走或者往右走；
规定机器人必须走 K 步，最终能来到P位置(P也是1~N中的一个)的方法有多少种
给定四个参数 N、M、K、P，返回方法数。
思路与解析
还是一样，我们首先先得写出递归版本

base case： 步数走完，判断当前位置是否是所要求的位置，如果是，那么则返回1，否则返回0。
在边界时，只能向一个方向走，因此限制方向。
在其他可以向左向右。
根据以上，写出递归过程。

/**
     *
     * @param N 位置
     * @param M 出发
     * @param K 步数
     * @param P 方法数
     * @return 到达数目
     */
    public static int ways1(int N, int M, int K, int P) {
        //参数无效返回
        if (N &lt; 2 || K &lt; 1 || M &lt; 1 || M &gt; N || P &lt; 1 || P &gt; N) {
            return 0;
        }
        // 总共N个位置，从M点出发，还剩K步，返回最终能达到P的方法数
        return walk(N, M, K, P);
    }

    /**
     *
     * @param N 位置为1 ~ N，固定参数
     * @param cur 当前在cur位置，可变参数
     * @param rest 还剩res步没有走，可变参数
     * @param P 最终目标位置是P，固定参数
     * @return 只能在1~N这些位置上移动，当前在cur位置，走完rest步之后，停在P位置的方法数作为返回值返回
     */
    private static int walk(int N, int cur, int rest, int P) {
        // 如果没有剩余步数了，当前的cur位置就是最后的位置
        // 如果最后的位置停在P上，那么之前做的移动是有效的
        // 如果最后的位置没在P上，那么之前做的移动是无效的
        if (rest == 0) {
            return cur == P ? 1 : 0;
        }
        // 如果还有rest步要走，而当前的cur位置在1位置上，那么当前这步只能从1走向2
        // 后续的过程就是，来到2位置上，还剩rest-1步要走
        if (cur == 1) {
            return walk(N, 2, rest - 1, P);
        }
        // 如果还有rest步要走，而当前的cur位置在N位置上，那么当前这步只能从N走向N-1
        // 后续的过程就是，来到N-1位置上，还剩rest-1步要走
        if (cur == N) {
            return walk(N, N - 1, rest - 1, P);
        }
        // 如果还有rest步要走，而当前的cur位置在中间位置上，那么当前这步可以走向左，也可以走向右
        // 走向左之后，后续的过程就是，来到cur-1位置上，还剩rest-1步要走
        // 走向右之后，后续的过程就是，来到cur+1位置上，还剩rest-1步要走
        // 走向左、走向右是截然不同的方法，所以总方法数要都算上
        return walk(N, cur + 1, rest - 1, P) + walk(N, cur - 1, rest - 1, P);
    }
那么，判断是否有重复。明显是存在的，举个例子，当我从3-&gt;2，与1-&gt;2，后面的步骤都是重复，因此可以优化。
有了如下代码：
 public static int ways2(int N, int M, int K, int P) {
        //参数无效返回
        if (N &lt; 2 || K &lt; 1 || M &lt; 1 || M &gt; N || P &lt; 1 || P &gt; N) {
            return 0;
        }
        int[][] dp = new int[K + 1][N + 1];
        dp[0][P] = 1;
        for (int i = 1; i &lt;= K; i++) {
            for (int j = 1; j &lt;= N; j++) {
                if (j == 1) {
                    dp[i][j] = dp[i - 1][2];
                } else if (j == N) {
                    dp[i][j] = dp[i - 1][N - 1];
                } else {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j + 1];
                }
            }
        }
        return dp[K][M];
    }
