线段树的目标：区间的查找、更新怎么比较快
概念


一种支持范围整体修改和范围整体查询的数据结构


解决的问题范畴：

大范围信息可以只由左、右两侧信息加工出，
而不必遍历左右两个子范围的具体状况



目标
给定一个数组arr，用户希望你实现如下三个方法

void add(int L, int R, int V) : 让数组arr[L…R]上每个数都加上V
void update(int L, int R, int V) : 让数组arr[L…R]上每个数都变成V
int sum(int L, int R) :让返回arr[L…R]这个范围整体的累加和

怎么让这三个方法，时间复杂度都是O(logN)
思路
想象如下图的结构：

假设现在是4个数[3, 2, 5, 7]的数组，先将数组进行拷贝，其中的0位置舍弃不用（方便进行位运算），将其构想成树的形式，父结点是1~4的和，父结点左孩子是1-2，右孩子是3-4，然后进行划分。
我们需要几个变量来实现上面的三个方法，sum【4 * N】，用于记录上面的每个值的和，之所以是 4 * N，是因为在进行划分的时候，会出现不满的情况（比如现在我有5个元素，不是2的次方），此时为了方便，我们需要进行补0的操作，因此，最大需要进行4* N的空间。
另外，还需要有一个懒加载值lazy[4 * N]，用于记录相加值，当我调用add方法时（如我要将1-4的位置加2），此时看区间是否符合，如果符合，则直接将此区间的lazy值变成所需加的值，然后sum的值进行累加（如1-4我要加2，那么sum的值加2*4=8的值）。
最后，还需要有一个更新值update[4 * N]，用于记录更新值，当我调用update方法时（如我要将1-4的位置变成2），此时看区间是否符合，如果符合，则直接将此区间的lazy值变成更新的值，将sum值进行变成更新值（如1-4我要变成2，那么sum的值变成2*4=8的值）。
最重要的问题是update与lazy进行下发的时机，如果说有一起的，那么则在下次懒加载的时候将上个懒加载值进行下发，然后更新一系列操作，如果进行更新与相加同时进行操作，先进性更新，在进行相加。
public static class SegmentTree {
		// arr[]为原序列的信息从0开始，但在arr里是从1开始的
		// sum[]模拟线段树维护区间和
		// lazy[]为累加懒惰标记
		// change[]为更新的值
		// update[]为更新慵懒标记
		private int MAXN;
		private int[] arr;
		private int[] sum;
		private int[] lazy;
		private int[] change;
		private boolean[] update;

		public SegmentTree(int[] origin) {
			MAXN = origin.length + 1;
			arr = new int[MAXN]; // arr[0] 不用  从1开始使用
			for (int i = 1; i &lt; MAXN; i++) {
				arr[i] = origin[i - 1];
			}
			sum = new int[MAXN &lt;&lt; 2]; // 用来支持脑补概念中，某一个范围的累加和信息
			lazy = new int[MAXN &lt;&lt; 2]; // 用来支持脑补概念中，某一个范围沒有往下傳遞的纍加任務
			change = new int[MAXN &lt;&lt; 2]; // 用来支持脑补概念中，某一个范围有没有更新操作的任务
			update = new boolean[MAXN &lt;&lt; 2]; // 用来支持脑补概念中，某一个范围更新任务，更新成了什么
		}

		private void pushUp(int rt) {
			sum[rt] = sum[rt &lt;&lt; 1] + sum[rt &lt;&lt; 1 | 1];
		}

    	//之前的，所有懒增加，和懒更新，从父范围，发给左右连个子范围
    	//fen&#039;fa&#039;c
		// ln表示左子树元素结点个数，rn表示右子树结点个数
		private void pushDown(int rt, int ln, int rn) {
			if (update[rt]) {
				update[rt &lt;&lt; 1] = true;
				update[rt &lt;&lt; 1 | 1] = true;
				change[rt &lt;&lt; 1] = change[rt];
				change[rt &lt;&lt; 1 | 1] = change[rt];
				lazy[rt &lt;&lt; 1] = 0;
				lazy[rt &lt;&lt; 1 | 1] = 0;
				sum[rt &lt;&lt; 1] = change[rt] * ln;
				sum[rt &lt;&lt; 1 | 1] = change[rt] * rn;
				update[rt] = false;
			}
			if (lazy[rt] != 0) {
				lazy[rt &lt;&lt; 1] += lazy[rt];
				sum[rt &lt;&lt; 1] += lazy[rt] * ln;
				lazy[rt &lt;&lt; 1 | 1] += lazy[rt];
				sum[rt &lt;&lt; 1 | 1] += lazy[rt] * rn;
				lazy[rt] = 0;
			}
		}

		// 在初始化阶段，先把sum数组，填好
		// 在arr[l~r]范围上，去build，1~N，
		// rt :  这个范围在sum中的下标
		public void build(int l, int r, int rt) {
			if (l == r) {
				sum[rt] = arr[l];
				return;
			}
			int mid = (l + r) &gt;&gt; 1;
			build(l, mid, rt &lt;&lt; 1);
			build(mid + 1, r, rt &lt;&lt; 1 | 1);
			pushUp(rt);
		}

		public void update(int L, int R, int C, int l, int r, int rt) {
			if (L &lt;= l &amp;&amp; r &lt;= R) {
				update[rt] = true;
				change[rt] = C;
				sum[rt] = C * (r - l + 1);
				lazy[rt] = 0;
				return;
			}
			// 当前任务躲不掉，无法懒更新，要往下发
			int mid = (l + r) &gt;&gt; 1;
			pushDown(rt, mid - l + 1, r - mid);
			if (L &lt;= mid) {
				update(L, R, C, l, mid, rt &lt;&lt; 1);
			}
			if (R &gt; mid) {
				update(L, R, C, mid + 1, r, rt &lt;&lt; 1 | 1);
			}
			pushUp(rt);
		}

		// L..R -&gt; 任务范围 ,所有的值累加上C
		// l,r -&gt; 表达的范围
		// rt  去哪找l，r范围上的信息
		public void add(int L, int R, int C,
				int l, int r, 
				int rt) {
			// 任务的范围彻底覆盖了，当前表达的范围
			if (L &lt;= l &amp;&amp; r &lt;= R) {
				sum[rt] += C * (r - l + 1);
				lazy[rt] += C;
				return;
			}
			// 要把任务往下发
			// 任务  L, R  没有把本身表达范围 l,r 彻底包住
			int mid = (l + r) &gt;&gt; 1;
			// 下发之前的lazy add任务
			pushDown(rt, mid - l + 1, r - mid);
			// 左孩子是否需要接到任务
			if (L &lt;= mid) {
				add(L, R, C, l, mid, rt &lt;&lt; 1);
			}
			// 右孩子是否需要接到任务
			if (R &gt; mid) {
				add(L, R, C, mid + 1, r, rt &lt;&lt; 1 | 1);
			}
			// 左右孩子做完任务后，我更新我的sum信息
			pushUp(rt);
		}

		public long query(int L, int R, int l, int r, int rt) {
			if (L &lt;= l &amp;&amp; r &lt;= R) {
				return sum[rt];
			}
			int mid = (l + r) &gt;&gt; 1;
			pushDown(rt, mid - l + 1, r - mid);
			long ans = 0;
			if (L &lt;= mid) {
				ans += query(L, R, l, mid, rt &lt;&lt; 1);
			}
			if (R &gt; mid) {
				ans += query(L, R, mid + 1, r, rt &lt;&lt; 1 | 1);
			}
			return ans;
		}

	}
