package class23;

public class AVLTree {
    public static class AVLNode&lt;K extends Comparable&lt;K&gt;, V&gt; {
        public K k;
        public V v;
        public AVLNode&lt;K, V&gt; l;
        public AVLNode&lt;K, V&gt; r;
        public int h;

        public AVLNode (K key, V value) {
            k = key;
            v = value;
            h = 1;
        }
    }

    public static class AVLTreeMap&lt;K extends Comparable&lt;K&gt;, V&gt; {
        private AVLNode&lt;K, V&gt; root;
        private int size;

        public AVLTreeMap () {
            root = null;
            size = 0;
        }

        private AVLNode&lt;K, V&gt; rightRotate (AVLNode&lt;K, V&gt; cur) {
            AVLNode&lt;K, V&gt; left = cur.l;
            cur.l = left.r;
            left.r = cur;
            cur.h = Math.max((cur.l != null ? cur.l.h : 0), (cur.r != null ? cur.r.h : 0)) + 1;
            left.h = Math.max((left.l != null ? left.l.h : 0), (left.r != null) ? left.r.h : 0);
            return left;
        }

        private AVLNode&lt;K, V&gt; leftRotate(AVLNode&lt;K,V&gt; cur) {
            AVLNode&lt;K, V&gt; right = cur.r;
            cur.r = right.l;
            right.l = cur;
            cur.h = Math.max((cur.l != null ? cur.l.h : 0), (cur.r != null ? cur.r.h : 0)) + 1;
            right.h = Math.max((right.l != null ? right.l.h : 0), (right.r != null) ? right.r.h : 0);
            return right;
        }

        private AVLNode&lt;K, V&gt; maintain(AVLNode&lt;K, V&gt; cur) {
            if (cur == null) {
                return null;
            }
            int leftHeight = cur.l != null ? cur.l.h : 0;
            int rightHeight = cur.r != null ? cur.r.h : 0;
            if (Math.abs(leftHeight - rightHeight) &gt; 1 ) {
                if (leftHeight &gt; rightHeight) {
                    int leftLeftHeight = cur.l != null &amp;&amp; cur.l.l != null ? cur.l.l.h : 0;
                    int leftRightHeight = cur.l != null &amp;&amp; cur.l.r != null ? cur.l.r.h : 0;
                    if (leftLeftHeight &gt;= leftRightHeight) {
                        cur = rightRotate(cur);
                    } else {
                        cur.l = leftRotate(cur.l);
                        cur.r = rightRotate(cur);
                    }
                } else {
                    int rightLeftHeight = cur.r != null &amp;&amp; cur.r.l != null ? cur.r.l.h : 0;
                    int rightRightHeight = cur.r != null &amp;&amp; cur.r.r != null ? cur.r.r.h : 0;
                    if (rightLeftHeight &gt;= rightRightHeight) {
                        cur = leftRotate(cur);
                    } else {
                        cur.r = rightRotate(cur.r);
                        cur = leftRotate(cur);
                    }
                }
            }
            return cur;
        }

        private AVLNode&lt;K, V&gt; findLastIndex (K key) {
            AVLNode&lt;K, V&gt; pre = root;
            AVLNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                pre = cur;
                if (key.compareTo(cur.k) == 0) {
                    break;
                } else if (key.compareTo(cur.k) &lt; 0) {
                    cur = cur.l;
                } else {
                    cur = cur.r;
                }
            }
            return pre;
        }


        private AVLNode&lt;K, V&gt; findLastNoSmallIndex (K key) {
            AVLNode&lt;K, V&gt; ans = null;
            AVLNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                if (key.compareTo(cur.k) == 0) {
                    ans = cur;
                    break;
                } else if (key.compareTo(cur.k) &lt; 0) {
                    ans = cur;
                    cur = cur.l;
                } else {
                    cur = cur.r;
                }
            }
            return ans;
        }

        private AVLNode&lt;K, V&gt; findLastNoBigIndex(K key) {
            AVLNode&lt;K, V&gt; ans = null;
            AVLNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                if (key.compareTo(cur.k) == 0) {
                    ans = cur;
                    break;
                } else if (key.compareTo(cur.k) &lt; 0) {
                    cur = cur.l;
                } else {
                    ans = cur;
                    cur = cur.r;
                }
            }
            return ans;
        }

        private AVLNode&lt;K, V&gt; add (AVLNode&lt;K, V&gt; cur, K key, V value) {
            if (cur == null) {
                return new AVLNode&lt;K, V&gt;(key, value);
            } else {
                if (key.compareTo(cur.k) &lt; 0) {
                    cur.l = add (cur.l, key, value);
                } else {
                    cur.r = add(cur.r, key, value);
                }
                cur.h = Math.max(cur.l != null ? cur.l.h : 0, cur.r != null ? cur.r.h : 0) + 1;
                return maintain(cur);
            }
        }

        private AVLNode&lt;K, V&gt; delete (AVLNode&lt;K, V&gt; cur, K key) {
            if (key.compareTo(cur.k) &gt; 0) {
                cur.r = delete(cur.r, key);
            } else if (key.compareTo(cur.k) &lt; 0) {
                cur.l = delete(cur.l, key);
            } else {
                if (cur.l == null &amp;&amp; cur.r == null) {
                    cur = null;
                } else if (cur.l == null &amp;&amp; cur.r != null) {
                    cur = cur.r;
                } else if (cur.l != null &amp;&amp; cur.r == null){
                    cur = cur.l;
                } else {
                    AVLNode&lt;K, V&gt; des = cur.r;
                    while (des.l != null) {
                        des = des.l;
                    }
                    cur.r = delete(cur.r, des.k);
                    des.l = cur.l;
                    des.r = cur.r;
                    cur = des;
                }
            }
            if (cur != null) {
                cur.h = Math.max(cur.l != null ? cur.l.h : 0, cur.r != null ? cur.r.h : 0) + 1;
            }
            return maintain(cur);
        }

        public int size() {
            return size;
        }

        public boolean containsKey(K key) {
            if (key == null) {
                return false;
            }
            AVLNode&lt;K, V&gt; lastNode = findLastIndex(key);
            return lastNode != null &amp;&amp; key.compareTo(lastNode.k) == 0 ? true : false;
        }

        public void put (K key, V value) {
            if (key == null) {
                return;
            }
            AVLNode&lt;K, V&gt; lastNode = findLastIndex(key);
            if (lastNode != null &amp;&amp; key.compareTo(lastNode.k) == 0) {
                lastNode.v = value;
            } else {
                size++;
                root = add(root, key, value);
            }
        }

        public void remove (K key) {
            if (key == null) {
                return;
            }
            if (containsKey(key)) {
                size--;
                root = delete(root, key);
            }
        }

        public V get (K key) {
            if (key == null) {
                return null;
            }
            AVLNode&lt;K, V&gt; lastNode = findLastIndex(key);
            if (lastNode != null &amp;&amp; key.compareTo(lastNode.k) == 0) {
                return lastNode.v;
            }
            return null;
        }

        public K firstKey() {
            if (root == null) {
                return null;
            }
            AVLNode&lt;K, V&gt; cur = root;
            while (cur.l != null) {
                cur = cur.l;
            }
            return cur.k;
        }

        public K lastKey() {
            if (root == null) {
                return null;
            }
            AVLNode&lt;K, V&gt; cur = root;
            while (cur.r != null) {
                cur = cur.r;
            }
            return cur.k;
        }

        public K floorKey(K key) {
            if (key == null) {
                return null;
            }
            AVLNode&lt;K, V&gt; lastNoBigNode = findLastNoBigIndex(key);
            return lastNoBigNode == null ? null : lastNoBigNode.k;
        }

        public K ceilingKey(K key) {
            if (key == null) {
                return null;
            }
            AVLNode&lt;K, V&gt; lastNoSmallNode = findLastNoSmallIndex(key);
            return lastNoSmallNode == null ? null : lastNoSmallNode.k;
        }
    }
}
size-balance-tree
AVL树的问题
对于每一步都进行判断是否平衡，当数据量很大时，会影响效率。
步骤


让每一个叔叔节点为头的数，节点个数都不少于其任何一个侄子节点


也是从底层被影响节点开始向上做路径每个节点检查


与AVL树非常像，也是四种违规类型：LL、RR、LR、RL


与AVL树非常像，核心点是：

LL（做一次右旋）、RR（做一次左旋）
LR和RL（利用旋转让底层那个上到顶部）



与AVL树不同的是，每轮经过调整后，谁的孩子发生变化了，谁就再查


每个结点所在子树的结点个数不小于其兄弟的两个孩子所在子树的结点个数。不算重复的key，只算这个树上有多少不同的key。AVL维持了高度，SB树维持了节点的个数。

检查平衡性图解

LL：对X进行右旋

RR：对X进行左旋

LR： 将有问题的孙子节点旋转到整体顶部

public class SizeBalancedTreeMapByClass {
    public static class SBTNode&lt;K extends Comparable&lt;K&gt;, V&gt; {
        public K key;
        public V value;
        public SBTNode&lt;K, V&gt; l;
        public SBTNode&lt;K, V&gt; r;
        public int size;

        public SBTNode(K key, V value) {
            this.key = key;
            this.value = value;
            size = 1;
        }
    }

    public static class SizeBalancedTreeMap&lt;K extends Comparable&lt;K&gt;, V&gt; {
        private SBTNode&lt;K, V&gt; root;

        private SBTNode&lt;K, V&gt; rightRotate(SBTNode&lt;K, V&gt; cur) {
            SBTNode&lt;K, V&gt; leftNode = cur.l;
            cur.l = leftNode.r;
            leftNode.r = cur;
            leftNode.size = cur.size;
            cur.size = (cur.l != null ? cur.l.size : 0) + (cur.r != null ? cur.r.size : 0) + 1;
            return leftNode;
        }

        public SBTNode&lt;K, V&gt; leftRotate(SBTNode&lt;K, V&gt; cur) {
            SBTNode&lt;K, V&gt; rightNode = cur.r;
            cur.r = rightNode.l;
            rightNode.l = cur;
            rightNode.size = cur.size;
            cur.size = (cur.l != null ? cur.l.size : 0) + (cur.r != null ? cur.r.size : 0) + 1;
            return rightNode;
        }

        public SBTNode&lt;K, V&gt; maintain(SBTNode&lt;K, V&gt; cur) {
            if (cur == null) {
                return null;
            }
            if (cur.l != null &amp;&amp; cur.l.l != null &amp;&amp; cur.r != null &amp;&amp; cur.l.l.size &gt; cur.r.size) {
                cur = rightRotate(cur);
                cur.r = maintain(cur.r);
                cur = maintain(cur);
            } else if (cur.l != null &amp;&amp; cur.l.r != null &amp;&amp; cur.r != null &amp;&amp; cur.l.r.size &gt; cur.r.size) {
                cur.l = leftRotate(cur);
                cur = rightRotate(cur);
                cur.l = maintain(cur.l);
                cur.r = maintain(cur.r);
                cur = maintain(cur);
            } else if (cur.r != null &amp;&amp; cur.r.r != null &amp;&amp; cur.l != null &amp;&amp; cur.r.r.size &gt; cur.l.size) {
                cur = leftRotate(cur);
                cur.l = maintain(cur.l);
                cur = maintain(cur);
            } else if (cur.r != null &amp;&amp; cur.r.l != null &amp;&amp; cur.l != null &amp;&amp; cur.r.l.size &gt; cur.l.size) {
                cur.r = rightRotate(cur.r);
                cur = leftRotate(cur);
                cur.l = maintain(cur.l);
                cur.r = maintain(cur.r);
                cur = maintain(cur);
            }
            return cur;
        }

        private SBTNode&lt;K, V&gt; findLastIndex(K key) {
            SBTNode&lt;K, V&gt; pre = root;
            SBTNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                pre = cur;
                if (key.compareTo(cur.key) == 0) {
                    break;
                } else if (key.compareTo(cur.key) &lt; 0) {
                    cur = cur.l;
                } else {
                    cur = cur.r;
                }
            }
            return pre;
        }

        private SBTNode&lt;K, V&gt; findLastNoSmallIndex(K key) {
            SBTNode&lt;K, V&gt; ans = null;
            SBTNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                if (key.compareTo(cur.key) == 0) {
                    ans = cur;
                    break;
                } else if (key.compareTo(cur.key) &lt; 0) {
                    ans = cur;
                    cur = cur.l;
                } else {
                    cur = cur.r;
                }
            }
            return ans;
        }

        private SBTNode&lt;K, V&gt; findLastNoBigIndex(K key) {
            SBTNode&lt;K, V&gt; ans = null;
            SBTNode&lt;K, V&gt; cur = root;
            while (cur != null) {
                if (key.compareTo(cur.key) == 0) {
                    ans = cur;
                    break;
                } else if (key.compareTo(cur.key) &lt; 0) {
                    cur = cur.l;
                } else {
                    ans = cur;
                    cur = cur.r;
                }
            }
            return ans;
        }

        // 现在，以cur为头的树上，加(key, value)这样的记录
        // 加完之后，会对cur做检查，该调整调整
        // 返回，调整完之后，整棵树的新头部
        private SBTNode&lt;K, V&gt; add(SBTNode&lt;K, V&gt; cur, K key, V value) {
            if (cur == null) {
                return new SBTNode&lt;&gt;(key, value);
            } else {
                cur.size++;
                if (key.compareTo(cur.key) &lt; 0) {
                    cur.l = add(cur.l, key, value);
                } else {
                    cur.r = add(cur.r, key, value);
                }
                return maintain(cur);
            }
        }

        // 在cur这棵树上，删掉key所代表的节点
        // 返回cur这棵树的新头部
        private SBTNode&lt;K, V&gt; delete(SBTNode&lt;K, V&gt; cur, K key) {
            cur.size--;
            if (key.compareTo(cur.key) &gt; 0) {
                cur.r = delete(cur.r, key);
            } else if (key.compareTo(cur.key) &lt; 0) {
                cur.l = delete(cur.l, key);
            } else {
                if (cur.l == null &amp;&amp; cur.r == null) {
                    cur = null;
                } else if (cur.l == null &amp;&amp; cur.r != null) {
                    cur = cur.r;
                } else if (cur.l != null &amp;&amp; cur.r == null) {
                    cur = cur.l;
                } else {
                    SBTNode&lt;K, V&gt; pre = null;
                    SBTNode&lt;K, V&gt; des = cur.r;
                    des.size--;
                    while (des.l != null) {
                        pre = des;
                        des = des.l;
                        des.size--;
                    }
                    if (pre != null) {
                        pre.l = des.r;
                        des.r = cur.r;
                    }
                    des.l = cur.l;
                    des.size = des.l.size + (des.r == null ? 0 : des.r.size) + 1;
                    cur = des;
                }
            }
            return cur;
        }

        private SBTNode&lt;K, V&gt; getIndex(SBTNode&lt;K, V&gt; cur, int kth) {
            if (kth == (cur.l != null ? cur.l.size : 0) + 1) {
                return cur;
            } else if (kth &lt;= (cur.l != null ? cur.l.size : 0)) {
                return getIndex(cur.l, kth);
            } else {
                return getIndex(cur.r, kth - (cur.l != null ? cur.l.size : 0) - 1);
            }
        }

        private int size() {
            return root == null ? 0 : root.size;
        }

        public boolean containsKey(K key) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            SBTNode&lt;K, V&gt; lastNode = findLastIndex(key);
            return lastNode != null &amp;&amp; key.compareTo(lastNode.key) == 0 ? true :false;
        }

        public void put(K key, V value) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter&quot;);
            }
            SBTNode&lt;K, V&gt; lastNode = findLastIndex(key);
            if (lastNode != null &amp;&amp; key.compareTo(lastNode.key) == 0) {
                lastNode.value = value;
            } else {
                root = add (root, key, value);
            }
        }

        public void remove(K key) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            if (containsKey(key)) {
                root = delete(root, key);
            }
        }

        public K getIndexKey(int index) {
            if (index &lt; 0 || index &gt;= this.size()) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            return getIndex(root, index + 1).key;
        }

        public V getIndexValue(int index) {
            if (index &lt; 0 || index &gt;= this.size()) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            return getIndex(root, index + 1).value;
        }

        public V get(K key) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            SBTNode&lt;K, V&gt; lastNode = findLastIndex(key);
            if (lastNode != null &amp;&amp; key.compareTo(lastNode.key) == 0) {
                return lastNode.value;
            } else {
                return null;
            }
        }

        public K firstKey() {
            if (root == null) {
                return null;
            }
            SBTNode&lt;K, V&gt; cur = root;
            while (cur.l != null) {
                cur = cur.l;
            }
            return cur.key;
        }

        public K lastKey() {
            if (root == null) {
                return null;
            }
            SBTNode&lt;K, V&gt; cur = root;
            while (cur.r != null) {
                cur = cur.r;
            }
            return cur.key;
        }

        public K floorKey(K key) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            SBTNode&lt;K, V&gt; lastNoBigNode = findLastNoBigIndex(key);
            return lastNoBigNode == null ? null : lastNoBigNode.key;
        }

        public K ceilingKey(K key) {
            if (key == null) {
                throw new RuntimeException(&quot;invalid parameter.&quot;);
            }
            SBTNode&lt;K, V&gt; lastNoSmallNode = findLastNoSmallIndex(key);
            return lastNoSmallNode == null ? null : lastNoSmallNode.key;
        }
    }
跳表
可以先看一篇文章，直接看，自己总结的不如这篇

结构上根本和搜索二叉树无关
利用随机概率分布来使得高层索引可以无视数据规律，做到整体性能优良
思想是所有有序表中最先进的
结构简单就是多级单链表

// 跳表的节点定义
	public static class SkipListNode&lt;K extends Comparable&lt;K&gt;, V&gt; {
		public K key;
		public V val;
		public ArrayList&lt;SkipListNode&lt;K, V&gt;&gt; nextNodes;

		public SkipListNode(K k, V v) {
			key = k;
			val = v;
			nextNodes = new ArrayList&lt;SkipListNode&lt;K, V&gt;&gt;();
		}

		// 遍历的时候，如果是往右遍历到的null(next == null), 遍历结束
		// 头(null), 头节点的null，认为最小
		// node  -&gt; 头，node(null, &quot;&quot;)  node.isKeyLess(!null)  true
		// node里面的key是否比otherKey小，true，不是false



		public boolean isKeyLess(K otherKey) {
			//  otherKey == null -&gt; false 
			return otherKey != null &amp;&amp; (key == null || key.compareTo(otherKey) &lt; 0);
		}

		public boolean isKeyEqual(K otherKey) {
			return (key == null &amp;&amp; otherKey == null)
					|| (key != null &amp;&amp; otherKey != null &amp;&amp; key.compareTo(otherKey) == 0);
		}

	}

	public static class SkipListMap&lt;K extends Comparable&lt;K&gt;, V&gt; {
		private static final double PROBABILITY = 0.5; // &lt; 0.5 继续做，&gt;=0.5 停
		private SkipListNode&lt;K, V&gt; head;
		private int size;
		private int maxLevel;

		public SkipListMap() {
			head = new SkipListNode&lt;K, V&gt;(null, null);
			head.nextNodes.add(null);
			size = 0;
			maxLevel = 0;
		}

		// 从最高层开始，一路找下去，
		// 最终，找到第0层的&lt;key的最右的节点
		private SkipListNode&lt;K, V&gt; mostRightLessNodeInTree(K key) {
			if (key == null) {
				return null;
			}
			int level = maxLevel;
			SkipListNode&lt;K, V&gt; cur = head;
			while (level &gt;= 0) { // 从上层跳下层
				//  cur  level  -&gt; level-1
				cur = mostRightLessNodeInLevel(key, cur, level--);
			}
			return cur;
		}

		// 在level层里，如何往右移动
		// 现在来到的节点是cur，来到了cur的level层，在level层上，找到&lt;key最后一个节点并返回
		private SkipListNode&lt;K, V&gt; mostRightLessNodeInLevel(K key, 
				SkipListNode&lt;K, V&gt; cur, 
				int level) {
			SkipListNode&lt;K, V&gt; next = cur.nextNodes.get(level);
			while (next != null &amp;&amp; next.isKeyLess(key)) {
				cur = next;
				next = cur.nextNodes.get(level);
			}
			return cur;
		}

		public boolean containsKey(K key) {
			if (key == null) {
				return false;
			}
			SkipListNode&lt;K, V&gt; less = mostRightLessNodeInTree(key);
			SkipListNode&lt;K, V&gt; next = less.nextNodes.get(0);
			return next != null &amp;&amp; next.isKeyEqual(key);
		}

		public void put(K key, V value) {
			if (key == null) {
				return;
			}
			SkipListNode&lt;K, V&gt; less = mostRightLessNodeInTree(key);
			SkipListNode&lt;K, V&gt; find = less.nextNodes.get(0);
			if (find != null &amp;&amp; find.isKeyEqual(key)) {
				find.val = value;
			} else {
				size++;
				int newNodeLevel = 0;
				while (Math.random() &lt; PROBABILITY) {
					newNodeLevel++;
				}
				while (newNodeLevel &gt; maxLevel) {
					head.nextNodes.add(null);
					maxLevel++;
				}
				SkipListNode&lt;K, V&gt; newNode = new SkipListNode&lt;K, V&gt;(key, value);
				for (int i = 0; i &lt;= newNodeLevel; i++) {
					newNode.nextNodes.add(null);
				}
				int level = maxLevel;
				SkipListNode&lt;K, V&gt; pre = head;
				while (level &gt;= 0) {
					pre = mostRightLessNodeInLevel(key, pre, level);
					if (level &lt;= newNodeLevel) {
						newNode.nextNodes.set(level, pre.nextNodes.get(level));
						pre.nextNodes.set(level, newNode);
					}
					level--;
				}
			}
		}

		public V get(K key) {
			if (key == null) {
				return null;
			}
			SkipListNode&lt;K, V&gt; less = mostRightLessNodeInTree(key);
			SkipListNode&lt;K, V&gt; next = less.nextNodes.get(0);
			return next != null &amp;&amp; next.isKeyEqual(key) ? next.val : null;
		}

		public void remove(K key) {
			if (containsKey(key)) {
				size--;
				int level = maxLevel;
				SkipListNode&lt;K, V&gt; pre = head;
				while (level &gt;= 0) {
					pre = mostRightLessNodeInLevel(key, pre, level);
					SkipListNode&lt;K, V&gt; next = pre.nextNodes.get(level);
					// 1）在这一层中，pre下一个就是key
					// 2）在这一层中，pre的下一个key是&gt;要删除key
					if (next != null &amp;&amp; next.isKeyEqual(key)) {
						// free delete node memory -&gt; C++
						// level : pre -&gt; next(key) -&gt; ...
						pre.nextNodes.set(level, next.nextNodes.get(level));
					}
					// 在level层只有一个节点了，就是默认节点head
					if (level != 0 &amp;&amp; pre == head &amp;&amp; pre.nextNodes.get(level) == null) {
						head.nextNodes.remove(level);
						maxLevel--;
					}
					level--;
				}
			}
		}

		public K firstKey() {
			return head.nextNodes.get(0) != null ? head.nextNodes.get(0).key : null;
		}

		public K lastKey() {
			int level = maxLevel;
			SkipListNode&lt;K, V&gt; cur = head;
			while (level &gt;= 0) {
				SkipListNode&lt;K, V&gt; next = cur.nextNodes.get(level);
				while (next != null) {
					cur = next;
					next = cur.nextNodes.get(level);
				}
				level--;
			}
			return cur.key;
		}

		public K ceillingKey(K key) {
			if (key == null) {
				return null;
			}
			SkipListNode&lt;K, V&gt; less = mostRightLessNodeInTree(key);
			SkipListNode&lt;K, V&gt; next = less.nextNodes.get(0);
			return next != null ? next.key : null;
		}

		public K floorKey(K key) {
			if (key == null) {
				return null;
			}
			SkipListNode&lt;K, V&gt; less = mostRightLessNodeInTree(key);
			SkipListNode&lt;K, V&gt; next = less.nextNodes.get(0);
			return next != null &amp;&amp; next.isKeyEqual(key) ? next.key : less.key;
		}

		public int size() {
			return size;
		}

	}
