public static int countRangeSum(int[] nums, int lower, int upper) {
        SBTBalancedTreeSet treeSet = new SBTBalancedTreeSet();
        long sum = 0;
        int ans = 0;
        treeSet.add(0);
        for (int i = 0; i &lt; nums.length; i++) {
            sum += nums[i];
            long lessLowers = treeSet.moreKeySize(sum - lower);
            long moreUppers = treeSet.lessKeySize(sum - upper);
            ans += i + 1 - lessLowers - moreUppers;
            treeSet.add(sum);
        }
        return ans;
    }

    public static class SBTNode {
        public long key;
        public SBTNode left;
        public SBTNode right;
        public long size;// 不同key的size
        public long all;// 总的size
        public SBTNode(long key) {
            this.key = key;
            size = 1;
            all = 1;
        }
    }

    public static class SBTBalancedTreeSet {
        private SBTNode root;
        private HashSet&lt;Long&gt; set = new HashSet&lt;&gt;();

        private SBTNode rightRotate (SBTNode cur) {
            long same = cur.all - (cur.left != null ? cur.left.all : 0) - (cur.right != null ? cur.right.all : 0);
            SBTNode leftNode = cur.left;
            cur.left = leftNode.right;
            leftNode.right = cur;
            leftNode.size = cur.size;
            cur.size = (cur.left != null ? cur.left.size : 0) + (cur.right != null ? cur.right.size : 0) + 1;
            leftNode.all = cur.all;
            cur.all = (cur.left != null ?  cur.left.all : 0) + (cur.right != null ? cur.right.all : 0) + same;
            return leftNode;
        }

        public SBTNode leftRotate (SBTNode cur) {
            long same = cur.all - (cur.left != null ? cur.left.all : 0) - (cur.right != null ? cur.right.all : 0);
            SBTNode rightNode = cur.right;
            cur.right = rightNode.left;
            rightNode.left = cur;
            rightNode.size = cur.size;
            cur.size = (cur.left != null ? cur.left.size : 0) + (cur.right != null ? cur.right.size : 0) + 1;
            rightNode.all = cur.all;
            cur.all = (cur.left != null ?  cur.left.all : 0) + (cur.right != null ? cur.right.all : 0) + same;
            return rightNode;
        }

        private SBTNode maintain(SBTNode cur) {
            if (cur == null) {
                return null;
            }
            if (cur.left != null &amp;&amp; cur.left.left != null &amp;&amp; cur.right != null &amp;&amp; cur.left.left.size &gt; cur.right.size) {
                cur = rightRotate(cur);
                cur.right = maintain(cur.right);
                cur = maintain(cur);
            } else if (cur.left != null &amp;&amp; cur.left.right != null &amp;&amp; cur.right != null &amp;&amp; cur.left.right.size &gt; cur.right.size) {
                cur.left = leftRotate(cur.left);
                cur = rightRotate(cur);
                cur.left = maintain(cur.left);
                cur.right = maintain(cur.right);
                cur = maintain(cur);
            } else if (cur.right != null &amp;&amp; cur.right.right != null &amp;&amp; cur.left != null &amp;&amp; cur.right.right.size &gt; cur.left.size) {
                cur = leftRotate(cur);
                cur.left = maintain(cur.left);
                cur = maintain(cur);
            } else if (cur.right != null &amp;&amp; cur.right.left != null &amp;&amp; cur.left != null &amp;&amp; cur.right.left.size &gt; cur.left.size) {
                cur.right = rightRotate(cur.right);
                cur = leftRotate(cur);
                cur.left = maintain(cur.left);
                cur.right = maintain(cur.right);
                cur = maintain(cur);
            }
            return cur;
        }

        public SBTNode add(SBTNode cur, long key, boolean contains) {
            if (cur == null) {
                return new SBTNode(key);
            } else {
                cur.all++;
                if (key == cur.key) {
                    return cur;
                } else {
                    if (!contains) {
                        cur.size++;
                    }
                    if (key &lt; cur.key) {
                        cur.left = add(cur.left, key, contains);
                    } else {
                        cur.right = add(cur.right, key, contains);
                    }
                    return maintain(cur);
                }
            }

             public void add(long sum) {
            boolean contains = set.contains(sum);
            root = add(root, sum, contains);
            set.add(sum);
        }

        public long lessKeySize(long key) {
            SBTNode cur = root;
            long ans = 0;
            while (cur != null) {
                if (key == cur.key) {
                    return ans + (cur.left != null ? cur.left.all : 0);
                } else if (key &lt; cur.key) {
                    cur = cur.left;
                } else {
                    ans += cur.all - (cur.right != null ? cur.right.all : 0);
                    cur = cur.right;
                }
            }
            return ans;
        }

        public long moreKeySize(long key) {
            return root != null ? (root.all - lessKeySize(key + 1)) : 0;
        }
        }
