public static class SBTNode&lt;K extends Comparable&lt;K&gt;&gt; {
		public K key;
		public SBTNode&lt;K&gt; l;
		public SBTNode&lt;K&gt; r;
		public int size;

		public SBTNode(K k) {
			key = k;
			size = 1;
		}
	}

	public static class SizeBalancedTreeMap&lt;K extends Comparable&lt;K&gt;&gt; {
		private SBTNode&lt;K&gt; root;

		private SBTNode&lt;K&gt; rightRotate(SBTNode&lt;K&gt; cur) {
			SBTNode&lt;K&gt; leftNode = cur.l;
			cur.l = leftNode.r;
			leftNode.r = cur;
			leftNode.size = cur.size;
			cur.size = (cur.l != null ? cur.l.size : 0) + (cur.r != null ? cur.r.size : 0) + 1;
			return leftNode;
		}

		private SBTNode&lt;K&gt; leftRotate(SBTNode&lt;K&gt; cur) {
			SBTNode&lt;K&gt; rightNode = cur.r;
			cur.r = rightNode.l;
			rightNode.l = cur;
			rightNode.size = cur.size;
			cur.size = (cur.l != null ? cur.l.size : 0) + (cur.r != null ? cur.r.size : 0) + 1;
			return rightNode;
		}

		private SBTNode&lt;K&gt; maintain(SBTNode&lt;K&gt; cur) {
			if (cur == null) {
				return null;
			}
			int leftSize = cur.l != null ? cur.l.size : 0;
			int leftLeftSize = cur.l != null &amp;&amp; cur.l.l != null ? cur.l.l.size : 0;
			int leftRightSize = cur.l != null &amp;&amp; cur.l.r != null ? cur.l.r.size : 0;
			int rightSize = cur.r != null ? cur.r.size : 0;
			int rightLeftSize = cur.r != null &amp;&amp; cur.r.l != null ? cur.r.l.size : 0;
			int rightRightSize = cur.r != null &amp;&amp; cur.r.r != null ? cur.r.r.size : 0;
			if (leftLeftSize &gt; rightSize) {
				cur = rightRotate(cur);
				cur.r = maintain(cur.r);
				cur = maintain(cur);
			} else if (leftRightSize &gt; rightSize) {
				cur.l = leftRotate(cur.l);
				cur = rightRotate(cur);
				cur.l = maintain(cur.l);
				cur.r = maintain(cur.r);
				cur = maintain(cur);
			} else if (rightRightSize &gt; leftSize) {
				cur = leftRotate(cur);
				cur.l = maintain(cur.l);
				cur = maintain(cur);
			} else if (rightLeftSize &gt; leftSize) {
				cur.r = rightRotate(cur.r);
				cur = leftRotate(cur);
				cur.l = maintain(cur.l);
				cur.r = maintain(cur.r);
				cur = maintain(cur);
			}
			return cur;
		}

		private SBTNode&lt;K&gt; findLastIndex(K key) {
			SBTNode&lt;K&gt; pre = root;
			SBTNode&lt;K&gt; cur = root;
			while (cur != null) {
				pre = cur;
				if (key.compareTo(cur.key) == 0) {
					break;
				} else if (key.compareTo(cur.key) &lt; 0) {
					cur = cur.l;
				} else {
					cur = cur.r;
				}
			}
			return pre;
		}

		private SBTNode&lt;K&gt; add(SBTNode&lt;K&gt; cur, K key) {
			if (cur == null) {
				return new SBTNode&lt;K&gt;(key);
			} else {
				cur.size++;
				if (key.compareTo(cur.key) &lt; 0) {
					cur.l = add(cur.l, key);
				} else {
					cur.r = add(cur.r, key);
				}
				return maintain(cur);
			}
		}

		private SBTNode&lt;K&gt; delete(SBTNode&lt;K&gt; cur, K key) {
			cur.size--;
			if (key.compareTo(cur.key) &gt; 0) {
				cur.r = delete(cur.r, key);
			} else if (key.compareTo(cur.key) &lt; 0) {
				cur.l = delete(cur.l, key);
			} else {
				if (cur.l == null &amp;&amp; cur.r == null) {
					// free cur memory -&gt; C++
					cur = null;
				} else if (cur.l == null &amp;&amp; cur.r != null) {
					// free cur memory -&gt; C++
					cur = cur.r;
				} else if (cur.l != null &amp;&amp; cur.r == null) {
					// free cur memory -&gt; C++
					cur = cur.l;
				} else {
					SBTNode&lt;K&gt; pre = null;
					SBTNode&lt;K&gt; des = cur.r;
					des.size--;
					while (des.l != null) {
						pre = des;
						des = des.l;
						des.size--;
					}
					if (pre != null) {
						pre.l = des.r;
						des.r = cur.r;
					}
					des.l = cur.l;
					des.size = des.l.size + (des.r == null ? 0 : des.r.size) + 1;
					// free cur memory -&gt; C++
					cur = des;
				}
			}
			return cur;
		}

		private SBTNode&lt;K&gt; getIndex(SBTNode&lt;K&gt; cur, int kth) {
			if (kth == (cur.l != null ? cur.l.size : 0) + 1) {
				return cur;
			} else if (kth &lt;= (cur.l != null ? cur.l.size : 0)) {
				return getIndex(cur.l, kth);
			} else {
				return getIndex(cur.r, kth - (cur.l != null ? cur.l.size : 0) - 1);
			}
		}

		public int size() {
			return root == null ? 0 : root.size;
		}

		public boolean containsKey(K key) {
			if (key == null) {
				throw new RuntimeException(&quot;invalid parameter.&quot;);
			}
			SBTNode&lt;K&gt; lastNode = findLastIndex(key);
			return lastNode != null &amp;&amp; key.compareTo(lastNode.key) == 0 ? true : false;
		}

		public void add(K key) {
			if (key == null) {
				throw new RuntimeException(&quot;invalid parameter.&quot;);
			}
			SBTNode&lt;K&gt; lastNode = findLastIndex(key);
			if (lastNode == null || key.compareTo(lastNode.key) != 0) {
				root = add(root, key);
			}
		}

		public void remove(K key) {
			if (key == null) {
				throw new RuntimeException(&quot;invalid parameter.&quot;);
			}
			if (containsKey(key)) {
				root = delete(root, key);
			}
		}

		public K getIndexKey(int index) {
			if (index &lt; 0 || index &gt;= this.size()) {
				throw new RuntimeException(&quot;invalid parameter.&quot;);
			}
			return getIndex(root, index + 1).key;
		}

	}

	public static class Node implements Comparable&lt;Node&gt; {
		public int index;
		public int value;

		public Node(int i, int v) {
			index = i;
			value = v;
		}

		@Override
		public int compareTo(Node o) {
			return value != o.value ? Integer.valueOf(value).compareTo(o.value)
					: Integer.valueOf(index).compareTo(o.index);
		}
	}

	public static double[] medianSlidingWindow(int[] nums, int k) {
		SizeBalancedTreeMap&lt;Node&gt; map = new SizeBalancedTreeMap&lt;&gt;();
		for (int i = 0; i &lt; k - 1; i++) {
			map.add(new Node(i, nums[i]));
		}
		double[] ans = new double[nums.length - k + 1];
		int index = 0;
		for (int i = k - 1; i &lt; nums.length; i++) {
			map.add(new Node(i, nums[i]));
			if (map.size() % 2 == 0) {
				Node upmid = map.getIndexKey(map.size() / 2 - 1);
				Node downmid = map.getIndexKey(map.size() / 2);
				ans[index++] = ((double) upmid.value + (double) downmid.value) / 2;
			} else {
				Node mid = map.getIndexKey(map.size() / 2);
				ans[index++] = (double) mid.value;
			}
			map.remove(new Node(i - k + 1, nums[i - k + 1]));
		}
		return ans;
	}
