题目五
给定一个N*N的矩阵matrix，只有0和1两种值，返回边框全是1的最大正方形的边长长度。
例如:
01111
01001
01001
01111
01011
其中边框全是1的最大正方形的大小为4*4，所以返回4。
解析
需要知道：在一个矩形中，存在有大概O(N^4)个矩形，存在O(N^3)个正方形。
那么，如果说我们有了一个点对应右边以及下面对应1的个数，那么这个时候我们就能得到这个边长的长度，此时我们就能得到一个答案，将每个位置进行枚举，我们就能得到对应的正方形边长，从中选取最大，就是我们想要的答案。
 public static void setBorderMap(int[][] m, int[][] right, int[][] down) {
        int r = m.length;
        int c = m[0].length;
        if (m[r - 1][c - 1] == 1) {
            right[r - 1][c - 1] = 1;
            down[r - 1][c - 1] = 1;
        }
        for (int i = r - 2; i != -1; i--) {
            if (m[i][c - 1] == 1) {
                right[i][c - 1] = 1;
                down[i][c - 1] = down[i + 1][c - 1] + 1;
            }
        }

        for (int i = c - 2; i != -1; i--) {
            if (m[r - 1][i] == 1) {
                right[r - 1][i] = right[r - 1][i + 1] + 1;
                down[r - 1][i] = 1;
            }
        }

        for (int i = r - 2; i != -1; i--) {
            for (int j = c - 2; j != -1; j--) {
                if (m[i][j] == 1) {
                    right[i][j] = right[i][j + 1] + 1;
                    down[i][j] = down[i + 1][j] + 1;
                }
            }
        }
    }

    public static int getMaxSize(int[][] m) {
        int[][] right = new int[m.length][m[0].length];
        int[][] down = new int[m.length][m[0].length];
        setBorderMap(m, right, down);

        for (int size = Math.min(m.length, m[0].length); size != 0; size--) {
            if (hasSizeOfBorder(size, right, down)) {
                return size;
            }
        }
        return 0;
    }

    public static boolean hasSizeOfBorder(int size, int[][] right, int[][] down) {
        for (int i = 0; i != right.length - size + 1; i++) {
            for (int j = 0; j != right[0].length - size + 1; j++) {
                if (right[i][j] &gt;= size &amp;&amp; down[i][j] &gt;= size
                        &amp;&amp; right[i + size - 1][j] &gt;= size
                        &amp;&amp; down[i][j + size - 1] &gt;= size) {
                    return true;
                }
            }
        }
        return false;
    }
题目六
给定一个正整数M，请构造出一个长度为M的数组arr，要求
对任意的i、j、k三个位置，如果i&lt;j&lt;k，都有arr[i] + arr[k] != 2*arr[j]
返回构造出的arr
思路
这个题目可以将其先进行划分，只要能保证有一个成立，就能基于此进行扩充，得出最终想要的结果。换句话说，即为：
对于任意一个已达标的m数组（如：arr[]={3,1,2}）
对这个数组进行奇变换（如将arr[]能变成{5，1，3}）
对这个数组进行偶变换（如将arr[]变成{6,2,4}）
那么，变换着后的也达标。

其实加1、加2、减100等等这种变换也能够达标，那为啥要奇偶变换呢？
因为好做啊，想象我们要扩大数组，如果我们前面拿一个达标的奇数数组，后面拿一个达标的偶数数组， （*一个odd + 一个even 一定不会等于 2 * 一个num* ）的。所以，拼接起来的大数组一定是达标的。

 public static int[] makeNo(int size) {
        if (size == 1) {
            return new int[1];
        }
        //size
        //一半长达标
        //7 ： 4
        //8 ： 4
        //[4个奇数][3个偶数]
        int halfSize = (size + 1) / 2;
        int[] base = makeNo(halfSize);
        // base -&gt; 等长奇数达标来
        // base -&gt; 等长偶数达标来
        int[] ans = new int[size];
        int index = 0;
        for (; index &lt; halfSize; index++) {
            ans[index] = base[index] * 2 + 1;
        }
        for (int i = 0; index &lt; size; index++, i++) {
            ans[index]  = base[i] * 2;
        }
        return ans;
    }
题目七
给定一个二叉树的头节点head，路径的规定有以下三种不同的规定：
1）路径必须是头节点出发，到叶节点为止，返回最大路径和
2）路径可以从任何节点出发，但必须往下走到达任何节点，返回最大路径和
3）路径可以从任何节点出发，到任何节点，返回最大路径和
解析
这是二叉树递归套路利用，不需要写思路，自己分析，自己搞懂。
public static int maxSum = Integer.MIN_VALUE;

    public static int maxPath(Node head) {
        p(head, 0);
        return maxSum;
    }

    private static void p(Node x, int pre) {
        if (x.left == null &amp;&amp; x.right == null) {
            maxSum = Math.max(maxSum, x.value);
        }
        if (x.left != null) {
            p(x.left, pre + x.value);
        }
        if (x.right != null) {
            p(x.right, pre + x.value);
        }
    }

    public static int maxDis(Node head) {
        if (head == null) {
            return 0;
        }
        return process2(head);
    }

    private static int process2(Node x) {
        //这里不能把null定为base case， 如果说用null，有能会将null误认为是一条路径。
        if (x.left == null &amp;&amp; x.right == null) {
            return x.value;
        }
        int next = Integer.MIN_VALUE;
        if (x.left != null) {
            next = process2(x.left);
        }
        if (x.right != null) {
            next = Math.max(next, process2(x.right));
        }
        return next + x.value;
    }

    public static int maxSum2(Node head) {
        if (head == null) {
            return 0;
        }
        return f(head).allTreeMaxSum;
    }

    public static class Info {
        public int allTreeMaxSum;
        public int fromHeadSum;

        public Info(int allTreeMaxSum, int fromHeadSum) {
            this.allTreeMaxSum = allTreeMaxSum;
            this.fromHeadSum = fromHeadSum;
        }
    }

    /**
     * 1)X无关的时候， 1、 左树上的整体最大路径和 2、 右树的整体最大路径和
     * 1)X有关的时候， 3、 X自己 4、 X往左走 5、X往右走
     *
     * @param x 结点
     * @return
     */
    public static Info f(Node x) {
        if (x == null) {
            return null;
        }
        Info leftInfo = f(x.left);
        Info rightInfo = f(x.right);
        int p1 = Integer.MIN_VALUE;
        if (leftInfo != null) {
            p1 = leftInfo.allTreeMaxSum;
        }
        int p2 = Integer.MIN_VALUE;
        if (rightInfo != null) {
            p2 = rightInfo.allTreeMaxSum;
        }
        int p3 = x.value;
        int p4 = Integer.MIN_VALUE;
        if (leftInfo != null) {
            p4 = x.value + leftInfo.fromHeadSum;
        }
        int p5 = Integer.MIN_VALUE;
        if (rightInfo != null) {
            p5 = x.value + rightInfo.fromHeadSum;
        }

        int allTreeMaxSum = Math.max(Math.max(Math.max(p1, p2), p3), Math.max(p4, p5));
        int fromHeadMaxSum = Math.max(Math.max(p3, p4), p5);
        return new Info(allTreeMaxSum, fromHeadMaxSum);
    }

    public static int maxSum3(Node head) {
        if (head == null) {
            return 0;
        }
        return f(head).allTreeMaxSum;
    }

    /**
     *  1)X无关的时候， 1、 左树上的整体最大路径和 2、 右树的整体最大路径和
     *  1)X有关的时候， 3、 X自己 4、 X往左走 5、X往右走 6、既往左，又往右
     * @param x 结点
     * @return
     */
    public static Info f2(Node x) {
        if (x == null) {
            return null;
        }
        Info leftInfo = f2(x.left);
        Info rightInfo = f2(x.right);
        int p1 = Integer.MIN_VALUE;
        if (leftInfo != null) {
            p1 = leftInfo.allTreeMaxSum;
        }
        int p2 = Integer.MIN_VALUE;
        if (rightInfo != null) {
            p2 = rightInfo.allTreeMaxSum;
        }
        int p3 = x.value;
        int p4 = Integer.MIN_VALUE;
        if (leftInfo != null) {
            p4 = x.value + leftInfo.fromHeadSum;
        }
        int p5 = Integer.MIN_VALUE;
        if (rightInfo != null) {
            p5 = x.value + rightInfo.fromHeadSum;
        }

        int p6 = Integer.MIN_VALUE;
        if (leftInfo != null &amp;&amp; rightInfo != null) {
            p6 = x.value + leftInfo.fromHeadSum + rightInfo.fromHeadSum;
        }

        int allTreeMaxSum = Math.max(Math.max(Math.max(p1, p2),p3), Math.max(Math.max(p4, p5), p6));
        int fromHeadMaxSum = Math.max(Math.max(p3, p4), p5);
        return new Info(allTreeMaxSum, fromHeadMaxSum);
    }

    public static int MAX = Integer.MIN_VALUE;

    public static int maxSum4(Node head) {
        if (head.left == null &amp;&amp; head.right == null) {
            MAX = Math.max(MAX, head.value);
        }
        int next = 0;
        if (head.left != null) {
            next = maxSum4(head.left);
        }
        if (head.right != null) {
            next = Math.max(next, maxSum4(head.right));
        }
        int ans = head.value + next;
        MAX = Math.max(MAX, ans);
        return ans;
    }

