public static boolean isContains(int[][] matrix, int K) {
       int row = 0;
       int col = matrix[0].length - 1;
       while (row &lt; matrix.length &amp;&amp; col &gt; - 1) {
           if (matrix[row][col] &lt; K) {
               row++;
           } else if (matrix[row][col] &gt; K) {
               col--;
           } else {
               return true;
           }
       }
       return false;
   }
