public static void printHalfMajor(int[] arr) {
        int cand = 0;
        int HP = 0;
        for (int i = 0; i &lt; arr.length; i++) {
            if (HP == 0) {
                cand = arr[i];
                HP = 1;
            } else if (arr[i] == cand) {
                HP++;
            } else {
                HP--;
            }
        }

        HP = 0;
        for (int i = 0; i &lt; arr.length; i++) {
            if (arr[i] == cand) {
                HP++;
            }
        }
        if (HP &gt; arr.length / 2) {
            System.out.println(cand);
        } else {
            System.out.println(&quot;no such number.&quot;);
        }
    }
public static void printKMajor(int[] arr, int K) {
        if (K &lt; 2) {
            System.out.println(&quot;the value of K is invalid.&quot;);
            return;
        }
        HashMap&lt;Integer, Integer&gt; cands = new HashMap&lt;&gt;();
        for (int i = 0; i &lt; arr.length; i++) {
            if (cands.containsKey(arr[i])) {
                cands.put(arr[i], cands.get(arr[i]) + 1);
            } else {
                if (cands.size() == K - 1) {
                    allCandsMinusOne(cands);
                } else {
                    cands.put(arr[i], 1);
                }
            }
        }

        HashMap&lt;Integer, Integer&gt; reals = getDeals(arr, cands);
        boolean hasPrint = false;
        for (Map.Entry&lt;Integer, Integer&gt; set : cands.entrySet()) {
            Integer key = set.getKey();
            if (reals.get(key) &gt; arr.length / K) {
                hasPrint = true;
                System.out.print(key + &quot; &quot;);
            }
        }
        System.out.println(hasPrint ? &quot;&quot; : &quot;no such number.&quot;);
    }

    public static void allCandsMinusOne(HashMap&lt;Integer, Integer&gt; map) {
        List&lt;Integer&gt; removeList = new LinkedList&lt;Integer&gt;();
        for (Map.Entry&lt;Integer, Integer&gt; set : map.entrySet()) {
            Integer key = set.getKey();
            Integer value = set.getValue();
            if (value == 1) {
                removeList.add(key);
            }
            map.put(key, value - 1);
            for (Integer removeKey : removeList) {
                map.remove(removeKey);
            }
        }
    }

    public static HashMap&lt;Integer, Integer&gt; getDeals(int[] arr, HashMap&lt;Integer, Integer&gt; cands) {
        HashMap&lt;Integer, Integer&gt; reals = new HashMap&lt;&gt;();
        for (int i = 0; i &lt; arr.length; i++) {
            int curNum = arr[i];
            if (cands.containsKey(curNum)) {
                if (reals.containsKey(curNum)) {
                    reals.put(curNum, reals.get(curNum) + 1);
                } else {
                    reals.put(curNum, 1);
                }
            }
        }
        return reals;
    }
题目八
首先，给你几个数据：
数组arr：表示几个咖啡机，这几个咖啡机生产一杯咖啡所需要的时间就是数组中的值，例如arr=[2,3,7]就表示第一台咖啡机生产一杯咖啡需要2单位时间，第二台需要3单位时间，第三台需要7单位时间。
int N：表示有N个人需要用咖啡机制作咖啡，每人一杯。
求每个人最早获得咖啡的时间。目标是所有人获取咖啡的时间都尽量早。
不同机器可以并行，相同机器只是串行
解析
优先队列
public static class Machine {
        public int start;
        public int work;

        public Machine(int start, int work) {
            this.start = start;
            this.work = work;
        }
    }

    public static class MachineComparator implements Comparator&lt;Machine&gt; {

        @Override
        public int compare(Machine o1, Machine o2) {
            return o1.start + o1.work - o2.start - o2.work;
        }
    }

    public static int[] bestChoices(int[] arr, int N) {
        int[] ans = new int[N];
        PriorityQueue&lt;Machine&gt; heap = new PriorityQueue&lt;&gt;(new MachineComparator());
        for (int i = 0; i &lt; arr.length; i++) {
            heap.add(new Machine(0, arr[i]));
        }
        for (int i = 0; i &lt; N; i++) {
            Machine cur = heap.poll();
            ans[i] = cur.start + cur.work;
            cur.start = ans[i];
            heap.add(cur);
        }
        return ans;
    }
