补充：上中位数
上中位数：等长、有序，两个合起来的中位数
进行二分法，选择A的中位数与B的中位数进行比较，相等返回，A&lt;B则在A的右边进行分割，A&gt;B则在A的左边进行分割，如果发现A中无论怎么划分都不存在，则证明在B
public static int getUpMedian(int[] A, int s1, int e1, int[] B, int s2, int e2, int kth) {
        int mid1 = 0;
        int mid2 = 0;
        while (s1 &lt; e1) {
            mid1 = (s1 + e1) / 2;
            mid2 = (s2 + e2) / 2;
//            int offset = ((e1 - s1 + 1) &amp; 1) ^ 1;
//            if (A[mid1] == B[mid2]) {
//                return A[mid1];
//            } else if (A[mid1] &gt; B[mid2]) {
//                return A[mid1];
//            } else {
//                s1 = mid1 + offset;
//                e2 = mid2;
//            }
            if (A[mid1] == B[mid2]) {
                return A[mid1];
            }
            if (((e1 - s1 + 1) &amp; 1) == 1) {
                if (A[mid1] &gt; B[mid2]) {
                    if (B[mid2] &gt;= A[mid1 -1]) {
                        return B[mid2];
                    }
                    e1 = mid1 - 1;
                    s2 = mid2 + 1;
                } else { //A[mid1] &lt; B[mid2]
                    if (A[mid1] &gt;= B[mid2 - 1]) {
                        return A[mid1];
                    }
                    e2 = mid2 - 1;
                    s1 = mid1 + 1;
                }
            } else {
                if (A[mid1] &gt; B[mid2]) {
                    e1 = mid1;
                    s2 = mid2 + 1;
                } else {
                    e2 = mid2;
                    s1 = mid1 + 1;
                }
            }
        }
        return Math.min(A[s1],B[s2]);
    }
